import Dexie from 'dexie';

class Database {
  constructor() {
    this.db = new Dexie('PointsRecorder');
    this.initDatabase();
  }

  initDatabase() {
    this.db.version(1).stores({
      users: 'id, name, createdAt',
      transactions: 'id, fromUserId, toUserId, createdAt',
      settings: 'key'
    });
  }

  // 用户操作
  async addUser(user) {
    return await this.db.users.add(user);
  }

  async getUsers() {
    return await this.db.users.toArray();
  }

  async updateUser(id, changes) {
    return await this.db.users.update(id, changes);
  }

  async deleteUser(id) {
    return await this.db.users.delete(id);
  }

  // 交易记录操作
  async addTransaction(transaction) {
    return await this.db.transactions.add(transaction);
  }

  async getTransactions() {
    return await this.db.transactions
      .orderBy('createdAt')
      .reverse()
      .toArray();
  }

  async getUserTransactions(userId) {
    return await this.db.transactions
      .where('fromUserId').equals(userId)
      .or('toUserId').equals(userId)
      .reverse()
      .sortBy('createdAt');
  }

  // 设置操作
  async setSetting(key, value) {
    return await this.db.settings.put({ key, value });
  }

  async getSetting(key) {
    const setting = await this.db.settings.get(key);
    return setting ? setting.value : null;
  }
}

export default new Database();
