import db from '@/services/database';
import { generateId } from '@/utils/uuid';

export default {
  namespaced: true,
  state: {
    list: []
  },
  getters: {
    userById: (state) => (id) => {
      return state.list.find(u => u.id === id);
    },
    totalScore: (state, getters, rootState, rootGetters) => {
      let total = 0;
      state.list.forEach(user => {
        total += rootGetters['transactions/userBalance'](user.id);
      });
      return total;
    }
  },
  mutations: {
    SET_USERS(state, users) {
      state.list = users;
    },
    ADD_USER(state, user) {
      state.list.push(user);
    },
    UPDATE_USER(state, { id, changes }) {
      const index = state.list.findIndex(u => u.id === id);
      if (index !== -1) {
        state.list.splice(index, 1, { ...state.list[index], ...changes });
      }
    },
    DELETE_USER(state, id) {
      state.list = state.list.filter(u => u.id !== id);
    }
  },
  actions: {
    async loadUsers({ commit }) {
      const users = await db.getUsers();
      commit('SET_USERS', users);
    },
    async addUser({ commit }, userData) {
      const user = {
        id: generateId(),
        name: userData.name,
        avatar: userData.avatar || '',
        createdAt: Date.now()
      };
      await db.addUser(user);
      commit('ADD_USER', user);
      return user;
    },
    async updateUser({ commit }, { id, changes }) {
      await db.updateUser(id, changes);
      commit('UPDATE_USER', { id, changes });
    },
    async deleteUser({ commit }, id) {
      await db.deleteUser(id);
      commit('DELETE_USER', id);
    }
  }
};
