export function validateUserName(name) {
  if (!name || name.trim().length === 0) {
    return '姓名不能为空';
  }
  if (name.length > 20) {
    return '姓名不能超过20个字符';
  }
  return true;
}

export function validatePointUnit(value) {
  const num = Number(value);
  if (isNaN(num) || num <= 0 || num > 10000) {
    return '积分单位必须在1-10000之间';
  }
  return true;
}
