<template>
  <div class="home" ref="homeEl">
    <van-nav-bar title="积分记录" fixed>
      <template #right>
        <van-icon name="setting-o" size="20" @click="goToSettings" />
      </template>
    </van-nav-bar>

    <div class="content">
      <div v-if="users.length > 0" class="drag-hint">长按并拖动卡片到另一位参与者即可转移积分</div>
      <user-card
        v-for="user in users"
        :key="user.id"
        :user="user"
        :balance="getUserBalance(user.id)"
        :transactions="getUserTransactions(user.id)"
        :is-over="overUserId === user.id && draggingUserId !== user.id"
        :is-dragging="draggingUserId === user.id"
        @detail-click="showDetail"
        @pointerdown.native="onPointerDown($event, user.id)"
      />
      <van-empty v-if="users.length === 0" description="暂无参与者，请前往设置添加" />
    </div>

    <!-- 拖拽预览幽灵元素 -->
    <div
      v-if="draggingUserId"
      class="drag-ghost"
      :style="ghostStyle"
    >
      {{ userById(draggingUserId) && userById(draggingUserId).name.charAt(0) }}
    </div>


    <van-popup v-model="showDetailModal" position="bottom" :style="{ height: '60%' }">
      <div class="detail-modal">
        <div class="modal-header">
          <h3>{{ selectedUserName }}的积分详情</h3>
          <van-icon name="cross" @click="showDetailModal = false" />
        </div>
        <div class="modal-content">
          <p class="current-score">
            当前积分：
            <span :class="selectedUserBalance >= 0 ? 'positive' : 'negative'">
              {{ selectedUserBalance >= 0 ? '+' : '' }}{{ selectedUserBalance }}
            </span>
          </p>
          <van-cell
            v-for="t in selectedUserTransactions"
            :key="t.id"
            :title="formatAmount(t)"
            :label="formatLabel(t)"
          />
          <van-empty v-if="selectedUserTransactions.length === 0" description="暂无记录" />
        </div>
      </div>
    </van-popup>
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex';
import UserCard from '@/components/UserCard.vue';

export default {
  name: 'Home',
  components: { UserCard },
  data() {
    return {
      showDetailModal: false,
      selectedUserId: null,
      draggingUserId: null,
      overUserId: null,
      ghostX: 0,
      ghostY: 0,
      startX: 0,
      startY: 0,
      isDragStarted: false
    };
  },
  computed: {
    ...mapState('users', { users: 'list' }),
    ...mapGetters('transactions', ['transactionsByUser', 'userBalance']),
    ...mapGetters('users', ['userById']),

    selectedUserName() {
      const user = this.userById(this.selectedUserId);
      return user ? user.name : '';
    },
    selectedUserBalance() {
      return this.getUserBalance(this.selectedUserId);
    },
    selectedUserTransactions() {
      return this.getUserTransactions(this.selectedUserId);
    },
    ghostStyle() {
      return {
        left: this.ghostX + 'px',
        top: this.ghostY + 'px'
      };
    }
  },
  methods: {
    ...mapActions('users', ['loadUsers']),
    ...mapActions('transactions', ['loadTransactions', 'createTransaction']),
    getUserBalance(userId) {
      return this.userBalance(userId);
    },
    getUserTransactions(userId) {
      return this.transactionsByUser(userId);
    },

    // Pointer drag logic
    onPointerDown(e, userId) {
      // 忽略按钮点击
      if (e.target.closest('button') || e.target.closest('.van-button')) return;

      this.startX = e.clientX;
      this.startY = e.clientY;
      this.isDragStarted = false;

      const onMove = (ev) => {
        const dx = ev.clientX - this.startX;
        const dy = ev.clientY - this.startY;

        if (!this.isDragStarted && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) {
          this.isDragStarted = true;
          this.draggingUserId = userId;
        }

        if (this.isDragStarted) {
          this.ghostX = ev.clientX - 24;
          this.ghostY = ev.clientY - 24;

          // 找出指针下方的卡片
          const el = document.elementFromPoint(ev.clientX, ev.clientY);
          const card = el && el.closest('[data-user-id]');
          this.overUserId = card ? card.dataset.userId : null;
        }
      };

      const onUp = (ev) => {
        document.removeEventListener('pointermove', onMove);
        document.removeEventListener('pointerup', onUp);

        if (this.isDragStarted && this.overUserId && this.overUserId !== this.draggingUserId) {
          this.onTransfer({ fromUserId: this.draggingUserId, toUserId: this.overUserId });
        }

        this.draggingUserId = null;
        this.overUserId = null;
        this.isDragStarted = false;
      };

      document.addEventListener('pointermove', onMove);
      document.addEventListener('pointerup', onUp);
    },

    onTransfer({ fromUserId, toUserId }) {
      const fromUser = this.userById(fromUserId);
      const toUser = this.userById(toUserId);
      const pointUnit = this.$store.getters['settings/pointUnit'];
      this.$dialog.confirm({
        title: '确认积分转移',
        message: `将 ${pointUnit} 分从「${fromUser.name}」转移给「${toUser.name}」？`
      }).then(async () => {
        await this.createTransaction({ fromUserId, toUserId });
        this.$toast.success(`已转移 ${pointUnit} 分`);
      }).catch(() => {});
    },

    showDetail(userId) {
      if (this.isDragStarted) return;
      this.selectedUserId = userId;
      this.showDetailModal = true;
    },
    formatAmount(t) {
      const isFrom = t.fromUserId === this.selectedUserId;
      return `${isFrom ? '+' : '-'}${t.amount}`;
    },
    formatLabel(t) {
      const fromUser = this.userById(t.fromUserId);
      const toUser = this.userById(t.toUserId);
      const isFrom = t.fromUserId === this.selectedUserId;
      const other = isFrom ? (toUser ? toUser.name : '未知') : (fromUser ? fromUser.name : '未知');
      return `${t.timestamp}  ${isFrom ? '借给' : '来自'}：${other}`;
    },
    goToSettings() {
      this.$router.push('/settings');
    }
  },
  async mounted() {
    await this.loadUsers();
    await this.loadTransactions();
  }
};
</script>

