import db from '@/services/database';
import { generateId } from '@/utils/uuid';
import dayjs from 'dayjs';

export default {
  namespaced: true,
  state: {
    list: [],
    loading: false
  },
  getters: {
    transactionsByUser: (state) => (userId) => {
      return state.list.filter(
        t => t.fromUserId === userId || t.toUserId === userId
      );
    },
    userBalance: (state, getters, rootState, rootGetters) => (userId) => {
      const pointUnit = rootGetters['settings/pointUnit'];
      let balance = 0;
      state.list.forEach(t => {
        if (t.fromUserId === userId) {
          balance += t.amount;
        }
        if (t.toUserId === userId) {
          balance -= t.amount;
        }
      });
      return balance;
    }
  },
  mutations: {
    SET_TRANSACTIONS(state, transactions) {
      state.list = transactions;
    },
    ADD_TRANSACTION(state, transaction) {
      state.list.unshift(transaction);
    },
    SET_LOADING(state, status) {
      state.loading = status;
    }
  },
  actions: {
    async loadTransactions({ commit }) {
      commit('SET_LOADING', true);
      const transactions = await db.getTransactions();
      commit('SET_TRANSACTIONS', transactions);
      commit('SET_LOADING', false);
    },
    async createTransaction({ commit, rootGetters }, { fromUserId, toUserId }) {
      const pointUnit = rootGetters['settings/pointUnit'];
      const transaction = {
        id: generateId(),
        fromUserId,
        toUserId,
        amount: pointUnit,
        timestamp: dayjs().format('YYYY-MM-DD HH:mm:ss'),
        createdAt: Date.now()
      };
      await db.addTransaction(transaction);
      commit('ADD_TRANSACTION', transaction);
      return transaction;
    }
  }
};
