import db from '@/services/database';

export default {
  namespaced: true,
  state: {
    pointUnit: 200,
    initialized: false
  },
  getters: {
    pointUnit: state => state.pointUnit,
    initialized: state => state.initialized
  },
  mutations: {
    SET_POINT_UNIT(state, value) {
      state.pointUnit = value;
    },
    SET_INITIALIZED(state, status) {
      state.initialized = status;
    }
  },
  actions: {
    async loadSettings({ commit }) {
      const pointUnit = await db.getSetting('pointUnit');
      const initialized = await db.getSetting('initialized');
      if (pointUnit) commit('SET_POINT_UNIT', pointUnit);
      if (initialized) commit('SET_INITIALIZED', initialized);
    },
    async updatePointUnit({ commit }, value) {
      await db.setSetting('pointUnit', value);
      commit('SET_POINT_UNIT', value);
    },
    async markInitialized({ commit }) {
      await db.setSetting('initialized', true);
      commit('SET_INITIALIZED', true);
    }
  }
};
