<template>
  <div class="settings">
    <van-nav-bar title="设置" left-arrow @click-left="$router.back()" fixed />

    <div class="content">
      <van-cell-group title="积分设置" inset>
        <van-field
          v-model="pointUnitInput"
          label="积分单位"
          type="number"
          placeholder="请输入积分单位"
          :error-message="pointUnitError"
          @blur="savePointUnit"
        >
          <template #right-icon>
            <span class="unit-label">分</span>
          </template>
        </van-field>
      </van-cell-group>

      <van-cell-group title="参与者管理" inset>
        <van-cell>
          <template #title>
            <van-button type="primary" size="small" block @click="showAddUser = true">
              + 添加参与者
            </van-button>
          </template>
        </van-cell>
        <van-swipe-cell v-for="user in users" :key="user.id">
          <div class="user-item">
            <div class="user-avatar">{{ user.name.charAt(0) }}</div>
            <span class="user-name-text">{{ user.name }}</span>
            <div class="action-btns">
              <van-button size="mini" type="info" plain @click="editUser(user)">编辑</van-button>
              <van-button size="mini" type="danger" plain @click="confirmDelete(user)">删除</van-button>
            </div>
          </div>
          <template #right>
            <van-button
              square
              type="danger"
              text="删除"
              style="height: 100%"
              @click="confirmDelete(user)"
            />
          </template>
        </van-swipe-cell>
        <van-empty v-if="users.length === 0" description="暂无参与者" />
      </van-cell-group>

      <div class="danger-zone">
        <van-button type="danger" plain block @click="confirmClearData">
          清空所有数据
        </van-button>
      </div>
    </div>

    <van-dialog
      v-model="showAddUser"
      :title="editingUser ? '编辑参与者' : '添加参与者'"
      show-cancel-button
      @confirm="submitUser"
      @cancel="resetUserForm"
    >
      <div class="dialog-content">
        <van-field
          v-model="userNameInput"
          label="姓名"
          placeholder="请输入姓名"
          :error-message="userNameError"
          autofocus
        />
      </div>
    </van-dialog>
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex';
import { validateUserName, validatePointUnit } from '@/utils/validator';

export default {
  name: 'Settings',
  data() {
    return {
      pointUnitInput: '',
      pointUnitError: '',
      showAddUser: false,
      userNameInput: '',
      userNameError: '',
      editingUser: null
    };
  },
  computed: {
    ...mapState('users', { users: 'list' }),
    ...mapGetters('settings', ['pointUnit'])
  },
  methods: {
    ...mapActions('users', ['loadUsers', 'addUser', 'updateUser', 'deleteUser']),
    ...mapActions('settings', ['updatePointUnit']),
    savePointUnit() {
      const result = validatePointUnit(this.pointUnitInput);
      if (result !== true) {
        this.pointUnitError = result;
        return;
      }
      this.pointUnitError = '';
      this.updatePointUnit(Number(this.pointUnitInput));
      this.$toast.success('已保存');
    },
    editUser(user) {
      this.editingUser = user;
      this.userNameInput = user.name;
      this.showAddUser = true;
    },
    async submitUser() {
      const result = validateUserName(this.userNameInput);
      if (result !== true) {
        this.userNameError = result;
        return;
      }
      if (this.editingUser) {
        await this.updateUser({ id: this.editingUser.id, changes: { name: this.userNameInput } });
        this.$toast.success('已更新');
      } else {
        await this.addUser({ name: this.userNameInput });
        this.$toast.success('已添加');
      }
      this.resetUserForm();
    },
    resetUserForm() {
      this.userNameInput = '';
      this.userNameError = '';
      this.editingUser = null;
      this.showAddUser = false;
    },
    confirmDelete(user) {
      this.$dialog.confirm({
        title: '删除参与者',
        message: `确定删除「${user.name}」吗？`
      }).then(() => {
        this.deleteUser(user.id);
        this.$toast.success('已删除');
      }).catch(() => {});
    },
    confirmClearData() {
      this.$dialog.confirm({
        title: '清空数据',
        message: '此操作将清空所有参与者和积分记录，不可恢复！'
      }).then(async () => {
        for (const user of [...this.users]) {
          await this.deleteUser(user.id);
        }
        this.$toast.success('已清空');
      }).catch(() => {});
    }
  },
  async mounted() {
    await this.loadUsers();
    this.pointUnitInput = String(this.pointUnit);
  }
};
</script>

