<template>
  <div
    class="user-card"
    :class="{ 'drag-over': isOver, 'dragging': isDragging }"
    :data-user-id="user.id"
  >
    <div class="avatar" :data-user-id="user.id">{{ userInitial }}</div>
    <div class="user-info" :data-user-id="user.id">
      <div class="user-name" :data-user-id="user.id">{{ user.name }}</div>
      <div class="user-score" :class="scoreClass" :data-user-id="user.id">{{ formattedScore }}</div>
      <div class="user-details" :data-user-id="user.id">{{ transactionDetails }}</div>
    </div>
    <van-button
      type="info"
      size="small"
      plain
      @click.stop="$emit('detail-click', user.id)"
    >
      查看详情
    </van-button>
  </div>
</template>

<script>
export default {
  name: 'UserCard',
  props: {
    user: { type: Object, required: true },
    balance: { type: Number, default: 0 },
    transactions: { type: Array, default: () => [] },
    isOver: { type: Boolean, default: false },
    isDragging: { type: Boolean, default: false }
  },
  computed: {
    userInitial() {
      return this.user.name ? this.user.name.charAt(0) : '?';
    },
    formattedScore() {
      const sign = this.balance >= 0 ? '+' : '';
      return `${sign}${this.balance}`;
    },
    scoreClass() {
      return this.balance >= 0 ? 'positive' : 'negative';
    },
    transactionDetails() {
      if (this.transactions.length === 0) return '';
      const amounts = this.transactions.map(t => {
        const sign = t.fromUserId === this.user.id ? '+' : '-';
        return `${sign}${t.amount}`;
      });
      return `(${amounts.join(', ')})`;
    }
  }
};
</script>

